import{z as o,x as l,o as e,c as B,q as t,j as A,D as E,d as n,s,S as i}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"对手方风险体系","description":"","frontmatter":{"title":"对手方风险体系","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/rk-counterparty-system.md","filePath":"quant/rk-counterparty-system.md","lastUpdated":1791063341000}'),p={name:"quant/rk-counterparty-system.md"};function C(d,a,m,h,u,_){const r=l("Mermaid");return e(),B("div",null,[a[2]||(a[2]=t('<h1 id="对手方风险体系" tabindex="-1">对手方风险体系 <a class="header-anchor" href="#对手方风险体系" aria-label="Permalink to &quot;对手方风险体系&quot;">​</a></h1><div class="epigraph"><p>对手方风险计量的对象不是违约概率，而是对手违约那一刻你替他垫了多少钱——暴露是随市场走的随机变量，不是一个数。</p><footer>—— 据 Pykhtin and Zhu, 2007；Gregory, *The xVA Challenge*, Wiley 整理</footer></div><p><a href="/quant/rk-liquidity-measurement">上一课</a>把退出成本与现金日程记入计量，但损失上界仍以「自己活着」为前提。当交易双边清算、对手可能违约时，缺口换成了另一个：违约那天的重置成本——把同样的交易重新找谁做、按什么价做。本课是计量单元的第三类：对手方信用风险的暴露画像、净额与抵押、CVA 与资本。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>对手方风险有两个不同的问题混在一起谈。结算风险：两腿交割不同步，付了款收不到货，1974 年 Herstatt 银行倒闭留下经典案例，现在由 PvP（付款对付款）机制与净额结算消除。揭约前风险：合约还有寿命，对手先违约，你手里只剩一张亏损后的替换单。错法有两类。用名义本金当暴露：利率掉期的名义动辄数亿，但平价时替换成本近零，夸大到没法用。用当前市值当暴露：期权卖出方此刻的 MTM 是正的小量，一年后深度实值时暴露放大数倍，低估到致命。两个极端都源于把随市场、随时间的随机过程压成一个常数。</p><p><span class="marginnote">常见误区：以为对手方风险就是「对手会不会倒」（违约概率）。体系真正难的是「他倒的那一刻我正暴露多少」——同一对手，平静期暴露可以是零，崩盘期翻成数亿；只盯评级，会漏掉暴露与市场联动的半个问题。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>暴露画像按时间与情景展开：蒙特卡洛生成因子路径，逐时点重估净额组合，得到暴露分布 \\(E(t)\\)；取高分位得潜在未来暴露 PFE，取均值 \\(\\mathrm{EPE}(t)=\\mathbb{E}[E(t)]\\) 作为定价与资本的代表量。净额先行：ISDA 主协议与 CSA 把同一对手的正负市值轧成净额，暴露从「逐笔之和」降为「净额之分布」，幅度差可达一个量级。抵押品第二层：变动保证金把暴露压回最小转让金额附近，初始抵押覆盖更远的尾部；代价是缺口风险——对手违约到抵押到账之间的保证金风险期里，市场还在动。第三层才是计量：\\(\\mathrm{CVA}\\) 把期望损失写为贴现暴露对违约密度的积分，\\(\\mathrm{CVA}\\approx \\mathrm{LGD}\\int \\mathrm{EE}^{\\ast}(t)\\,\\mathrm{dPD}(t)\\)；监管资本用 SA-CCR，以 \\(\\alpha=1.4\\) 的乘数覆盖错向与加总不足。</p><p><span class="marginnote">术语翻译：CVA（信用估值调整）就是给「对手可能赖账」这件事标价：把未来每个时点「他违约时我暴露多少」乘以「那时他违约的概率」，贴现后加总。它相当于从无风险价格里扣掉一笔预期坏账，使同一笔交易跟不同信用质量的对手成交时价格不同。</span></p>',9)),(e(),A(i,null,{default:E(()=>[s(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20LR%0A%20%20MC%5B%22%E8%92%99%E7%89%B9%E5%8D%A1%E6%B4%9B%E5%9B%A0%E5%AD%90%E8%B7%AF%E5%BE%84%22%5D%20--%3E%20PROF%5B%22%E9%80%90%E6%97%B6%E7%82%B9%E5%87%80%E9%A2%9D%E9%87%8D%E4%BC%B0%EF%BC%9A%E6%9A%B4%E9%9C%B2%E5%88%86%E5%B8%83%20E(t)%22%5D%0A%20%20NET%5B%22%E5%87%80%E9%A2%9D%E5%8D%8F%E8%AE%AE%E5%85%88%E8%BD%A7%E5%B7%AE%22%5D%20--%3E%20PROF%0A%20%20PROF%20--%3E%20STAT%5B%22PFE%20%E5%8F%96%E9%AB%98%E5%88%86%E4%BD%8D%EF%BC%8CEPE%20%E5%8F%96%E5%9D%87%E5%80%BC%22%5D%0A%20%20CSA%5B%22%E5%8F%98%E5%8A%A8%E4%BF%9D%E8%AF%81%E9%87%91%E5%8A%A0%E5%88%9D%E5%A7%8B%E6%8A%B5%E6%8A%BC%22%5D%20--%3E%20STAT%0A%20%20STAT%20--%3E%20USE%5B%22CVA%20%E8%AE%A1%E4%BB%B7%E4%B8%8E%20SA-CCR%20%E8%B5%84%E6%9C%AC%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p><span class="marginnote">保证金风险期（MPOR）是缺口风险的刻度：双边非集中清算的 OTC 衍生品至少取 \\(10\\) 个营业日，净额组合超五千笔或含难估值抵押时上调到 \\(20\\)。抵押越勤，缺口期越短、日常运营越重——这是运营成本换尾部风险的交换。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么画像必须是分布：暴露的上界由「市场先动、对手后倒」的联合事件决定，与市场风险共享同一组因子，因此对手方账簿的重估引擎往往直接复用上一课的流水线，只是把「自己的损失」换成「对手违约时自己的替换成本」。错向风险在这里入账：暴露与违约概率正相关——卖保护给高杠杆对手，它越接近倒下，你暴露越大；独立假设会系统性低估尾部，SA-CCR 的 \\(\\alpha\\) 就是给这个 ignorance 留的粗罚。CVA 把对手方风险翻译回市场风险：它随利差与汇率波动，可以对冲，对冲本身又引入新的暴露——这条链在 <a href="/quant/rc-xva-linkage">XVA 的联动</a>展开；违约概率与回收的估计交给<a href="/quant/rc-credit-portfolio">信用组合模型</a>。</p><p><span class="marginnote">数字实例：一笔名义 10 亿的平价利率掉期，签定时市值约 0，对手此刻违约你几乎不亏；两年后利率下行 200bp，同一笔掉期对你值 8000 万，若对手那时倒下，你就要亏掉这笔再找新对手重做。暴露随市场走，这就是它必须画成分布的原因。</span></p>',4)),(e(),A(i,null,{default:E(()=>[s(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20NET%5B%22%E5%87%80%E9%A2%9D%E4%B8%8E%E4%B8%BB%E5%8D%8F%E8%AE%AE%22%5D%20--%3E%20PROF%5B%22%E6%9A%B4%E9%9C%B2%E7%94%BB%E5%83%8F%EF%BC%9AEE%20%E4%B8%8E%20PFE%22%5D%0A%20%20CSA%5B%22%E6%8A%B5%E6%8A%BC%E5%93%81%EF%BC%9AVM%20%E5%8A%A0%20IM%22%5D%20--%3E%20PROF%0A%20%20PROF%20--%3E%20CVA%5B%22CVA%EF%BC%9A%E8%B4%B4%E7%8E%B0%E6%9A%B4%E9%9C%B2%E4%B9%98%E8%BF%9D%E7%BA%A6%E5%AF%86%E5%BA%A6%22%5D%0A%20%20PROF%20--%3E%20CAP%5B%22%E8%B5%84%E6%9C%AC%EF%BC%9ASA-CCR%22%5D%0A%20%20WWR%5B%22%E9%94%99%E5%90%91%EF%BC%9A%E6%9A%B4%E9%9C%B2%E4%B8%8E%20PD%20%E8%81%94%E5%8A%A8%22%5D%20--%3E%20CVA%0A%20%20WWR%20--%3E%20CAP%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不推导 CVA 的对冲组合，也不展开 CCP 的违约瀑布：中央清算把双边对手换成清算所，暴露降低了，换来的是会员的追缴义务与违约基金份额，资金侧归上一课的现金流梯级管。发行方信用与结构化产品的持有者风险是另一套文档与法律动作，不在本课。本课的画像按风险中性违约密度定价口径走，资本口径（监管映射）与会计口径（CVA 的 DVA 争议）各有规则，混用会把保守性与真实性搅在一起。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>对手方风险的计量单位是暴露分布，不是名义本金，也不是当前市值。</li><li>净额与抵押先于模型：协议结构决定暴露的数量级，模型只画剩下的形状。</li><li>缺口风险用保证金风险期刻度；错向风险用乘数或联合建模覆盖，独立假设低估尾部。</li><li>CVA 把对手方风险翻译回市场风险，对冲链与资本映射各有一套口径。</li><li>出处：Pykhtin and Zhu, 2007；Gregory, <em>The xVA Challenge</em>；BCBS, <em>The standardised approach for measuring counterparty credit risk exposures</em>, 2014；Herstatt 案例见国际清算银行清算风险报告。</li></ul>',4))])}const P=o(p,[["render",C]]);export{c as __pageData,P as default};
